// Filas a las que hay que generarles la HV adaptada:
//  - las que los scrapers marcaron solos con 'auto' en 'generar' (match >= umbral), y
//  - las que marques a mano con una X en 'generar'.
// Se saltean las que ya tienen link en 'hv_adaptada'. Maximo `max_hv_por_corrida` por corrida
// (las de mayor match primero) para terminar holgado antes de que la VM se apague a las 12:00.
const cfg = $('Config (API key + HV base)').first().json;
const hvBase = String(cfg.hv_base || '').replace(/\\n/g, '\n').trim();
if (!hvBase) throw new Error('HV_BASE_TEXT esta vacio: revisa el .env (debe ir en su propia linea) y reinicia el contenedor.');
if (String(cfg.prefijo_archivo || '').trim().length < 4) throw new Error('HV_PREFIJO_ARCHIVO vacio o muy corto en el .env (ej: HV_Nombre_Apellido).');
const MAX = Number(cfg.max_hv_por_corrida) || 5;

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const g = j.generar;
  const marcada = g === true || g === 1 ||
    ['true', 'x', '✓', 'verdadero', 'si', 'sí', '1', 'auto']
      .includes(String(g ?? '').trim().toLowerCase());
  const yaTiene = String(j.hv_adaptada || '').trim().length > 0;
  if (!marcada || yaTiene || !j.url) continue;
  out.push({ json: { ...j, hv_base: hvBase } });
}
out.sort((a, b) => (Number(b.json.match_pct) || 0) - (Number(a.json.match_pct) || 0));
return out.slice(0, MAX);

// Limpia el HTML de la oferta y arma el prompt para que la IA adapte la HV
const ctx = $('Loop ofertas').item.json;
const cfg = $('Config (API key + HV base)').first().json;
// ---- Utilidades compartidas: Gemini (API de Google AI Studio) + lectura de ofertas ----
const helpers = this.helpers;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Llama a Gemini por su endpoint compatible con OpenAI. Reintenta ante 429/5xx y, si el
// modelo principal sigue fallando (cuota o saturacion), cae a los modelos "lite" (cuota aparte).
async function gemini(prompt, { maxTokens = 8192, json = false } = {}) {
  const key = String(cfg.gemini_api_key || '').trim();
  if (!key) throw new Error('GEMINI_API_KEY vacia: revisa el .env y reinicia el contenedor (docker compose up -d).');
  const modelos = [cfg.gemini_model || 'gemini-3.8-flash', 'gemini-flash-lite-latest', 'gemini-3.5-flash-lite'];
  let err = '';
  for (let intento = 0; intento < 5; intento++) {
    const model = modelos[[0, 0, 1, 1, 2][intento]];
    try {
      const body = { model, messages: [{ role: 'user', content: prompt }], max_tokens: maxTokens, temperature: 0.2, reasoning_effort: 'low' };
      if (json) body.response_format = { type: 'json_object' };
      const resp = await helpers.httpRequest({
        method: 'POST',
        url: 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions',
        headers: { Authorization: 'Bearer ' + key, 'content-type': 'application/json' },
        body,
        json: true,
        timeout: 120000
      });
      const choice = (resp.choices || [])[0];
      const texto = ((choice && choice.message && choice.message.content) || '').trim();
      if (texto) return { texto, err: '' };
      err = 'Gemini sin texto: ' + JSON.stringify(resp).slice(0, 200);
    } catch (e) {
      err = (e.message || String(e)).slice(0, 300);
    }
    await sleep(intento === 0 ? 10000 : 25000);
  }
  return { texto: '', err };
}

function decodeEntities(str) {
  return String(str)
    .replace(/&#x([0-9A-Fa-f]+);/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)))
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'");
}
function limpiarHtml(str) {
  return decodeEntities(String(str)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' '))
    .replace(/\s+/g, ' ')
    .trim();
}

// Saca la descripcion de la oferta. Primero intenta el JSON-LD "JobPosting" (LinkedIn,
// Computrabajo y Elempleo lo publican), que trae solo la descripcion sin menus ni footer;
// si no esta, usa el texto plano de toda la pagina.
function extraerDescripcion(html, maxChars) {
  const s = String(html || '');
  const bloques = s.match(/<script[^>]*application\/ld\+json[^>]*>[\s\S]*?<\/script>/gi) || [];
  for (const b of bloques) {
    try {
      const data = JSON.parse(b.replace(/^<script[^>]*>/i, '').replace(/<\/script>$/i, ''));
      const lista = Array.isArray(data) ? data : (data['@graph'] || [data]);
      for (const d of lista) {
        if (d && d.description && /JobPosting/i.test(String(d['@type'] || ''))) {
          return limpiarHtml(decodeEntities(d.description)).slice(0, maxChars);
        }
      }
    } catch (e) { /* JSON-LD invalido: probar el siguiente */ }
  }
  return limpiarHtml(s).slice(0, maxChars);
}

async function traerDescripcion(url, maxChars) {
  try {
    const resp = await helpers.httpRequest({
      method: 'GET',
      url,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'es-CO,es;q=0.9,en;q=0.8',
        'Referer': 'https://www.google.com/'
      },
      timeout: 20000
    });
    const raw = (resp && (resp.body || resp.data)) || resp || '';
    return extraerDescripcion(typeof raw === 'string' ? raw : JSON.stringify(raw), maxChars);
  } catch (e) {
    return '';
  }
}

const raw = $input.first().json.data || $input.first().json.body || '';
let desc = extraerDescripcion(typeof raw === 'string' ? raw : JSON.stringify(raw), 6000);
if (desc.length < 200) desc = '(No se pudo leer la descripcion completa de la oferta.)';

const prompt = [
  'Eres experto en adaptar hojas de vida (HV) para pasar filtros ATS en procesos de seleccion' + (cfg.pais ? ' en ' + cfg.pais : '') + '.',
  '',
  'LO QUE SI DEBES HACER:',
  '- Usar la terminologia EXACTA de la oferta para describir lo que el candidato ya hizo.',
  '  Ejemplo: si la HV dice "seguimiento de tickets" y la oferta pide "gestion de incidentes",',
  '  escribelo como "gestion de incidentes". Es el mismo hecho, dicho con la palabra que busca el ATS.',
  '- Incluir las keywords de la oferta que correspondan a algo real de la HV base.',
  '- Dentro de cada cargo, poner primero los logros que mas se ajustan a esta oferta.',
  '- Reescribir el PERFIL PROFESIONAL (3-4 lineas) apuntado a este puesto puntual.',
  '',
  'LO QUE NO PUEDES HACER:',
  '- Inventar experiencia, empresas, titulos, certificaciones o anios que no esten en la HV base.',
  '- Agregar tecnologias o herramientas que el candidato nunca uso.',
  '- Inflar la duracion de un trabajo o el nivel de un idioma.',
  '- Inventar datos de contacto (si la HV base no trae telefono, no lo pongas).',
  '- Quitar o modificar ENLACES: todos los enlaces (URLs) de la HV base deben aparecer copiados EXACTAMENTE igual,',
  '  cada uno junto al elemento al que pertenece (LinkedIn y Portafolio en CONTACTO, el del titulo en FORMACION,',
  '  y cada certificado con su URL). Sirven para mostrar el perfil y los certificados: ninguno puede faltar.',
  '- Omitir la tarjeta profesional, el telefono o cualquier certificacion de la HV base.',
  '',
  'ORDEN: en EXPERIENCIA PROFESIONAL, FORMACION y CERTIFICACIONES, todo en orden cronologico del mas reciente',
  'al mas antiguo (por fecha, nunca por relevancia). Lo que si puedes reordenar por relevancia son los logros',
  'dentro de cada cargo y las habilidades.',
  'Regla: cada afirmacion de la HV adaptada tiene que poder defenderse en una entrevista.',
  '',
  'ORTOGRAFIA: escribe en español correcto, CON tildes y ñ (Ejecuté, técnicos, Diseñé, gestión, año),',
  'aunque estas instrucciones esten escritas sin tildes. Revisa que no queden palabras pegadas.',
  'Verbos en primera persona del preterito bien escritos: Realicé (no "Realizé"), Brindé, Lideré, Gestioné, Apoyé.',
  'El nombre del candidato se copia exacto de la HV base, letra por letra.',
  'Conserva en el perfil los años de experiencia que indique la HV base.',
  '',
  '=== HV BASE DEL CANDIDATO ===',
  ctx.hv_base,
  '',
  '=== OFERTA ===',
  'Puesto: ' + (ctx.titulo || ''),
  'Empresa: ' + (ctx.empresa || ''),
  'Ubicacion: ' + (ctx.ubicacion || ''),
  'Descripcion: ' + desc,
  '',
  '=== FORMATO DE SALIDA (siguelo exacto, se usa despues para darle diseno al documento) ===',
  'Linea 1: TITULO: Nombre Apellido | Rol/titulo profesional para este puesto',
  'Linea 2: CONTACTO: exactamente los mismos datos de contacto de la HV base, en el mismo orden y con sus enlaces completos',
  '  (telefono | email | tarjeta profesional | LinkedIn: <url> | Portafolio: <url>).',
  'Una linea en blanco.',
  'Despues, por cada seccion de la HV base, en este orden: PERFIL PROFESIONAL, EXPERIENCIA PROFESIONAL, FORMACION ACADEMICA, CERTIFICACIONES Y FORMACION COMPLEMENTARIA, HABILIDADES TECNICAS, HERRAMIENTAS, IDIOMAS:',
  '  - Una linea: SECCION: NOMBRE DE LA SECCION EN MAYUSCULAS',
  '  - Despues el contenido: parrafos normales en lineas simples, y para logros/tareas/listas una linea por punto empezando con "- ".',
  '  - En EXPERIENCIA, por cada cargo: una linea "Empresa | Cargo | Mes Anio – Mes Anio" y debajo sus logros con "- ".',
  '  - En CERTIFICACIONES, una linea por certificado: "- Nombre | Institucion | Anio | URL: <url>", del anio mas reciente al mas antiguo.',
  '  - Una linea en blanco antes de la siguiente SECCION.',
  'No uses markdown (nada de **, #, *, backticks). No agregues explicaciones ni comentarios: devuelve unicamente la HV en ese formato de lineas.'
].join('\n');

return [{ json: { ...ctx, prompt, desc } }];

// Pide a Gemini la HV adaptada. Los enlaces de la HV base (LinkedIn, portafolio, titulo y
// certificados) son obligatorios: si la respuesta omite alguno, se reintenta una vez
// diciendole cuales faltan. Si todo falla, el error queda como texto en el documento.
const inp = $input.first().json;
const cfg = $('Config (API key + HV base)').first().json;
// ---- Utilidades compartidas: Gemini (API de Google AI Studio) + lectura de ofertas ----
const helpers = this.helpers;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

