// Saca la descripcion de la oferta. Primero intenta el JSON-LD "JobPosting" (LinkedIn,
// Computrabajo y Elempleo lo publican), que trae solo la descripcion sin menus ni footer;
// si no esta, usa el texto plano de toda la pagina.
function extraerDescripcion(html, maxChars) {
  const s = String(html || '');
  const bloques = s.match(/<script[^>]*application\/ld\+json[^>]*>[\s\S]*?<\/script>/gi) || [];
  for (const b of bloques) {
    try {
      const data = JSON.parse(b.replace(/^<script[^>]*>/i, '').replace(/<\/script>$/i, ''));
      const lista = Array.isArray(data) ? data : (data['@graph'] || [data]);
      for (const d of lista) {
        if (d && d.description && /JobPosting/i.test(String(d['@type'] || ''))) {
          return limpiarHtml(decodeEntities(d.description)).slice(0, maxChars);
        }
      }
    } catch (e) { /* JSON-LD invalido: probar el siguiente */ }
  }
  return limpiarHtml(s).slice(0, maxChars);
}

async function traerDescripcion(url, maxChars) {
  try {
    const resp = await helpers.httpRequest({
      method: 'GET',
      url,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'es-CO,es;q=0.9,en;q=0.8',
        'Referer': 'https://www.google.com/'
      },
      timeout: 20000
    });
    const raw = (resp && (resp.body || resp.data)) || resp || '';
    return extraerDescripcion(typeof raw === 'string' ? raw : JSON.stringify(raw), maxChars);
  } catch (e) {
    return '';
  }
}

const URL_RE = /https?:\/\/[^\s|)]+/g;
const enlacesBase = [...new Set(String(inp.hv_base || '').match(URL_RE) || [])];
const limpiar = (t) => t.replace(/^```[a-z]*\s*/i, '').replace(/```\s*$/, '').trim();
const faltantes = (t) => enlacesBase.filter((u) => !t.includes(u));

let r = await gemini(inp.prompt, { maxTokens: 8192 });
let texto = limpiar(r.texto);

if (texto && faltantes(texto).length) {
  const extra = '\n\nIMPORTANTE: en tu respuesta anterior faltaron estos enlaces. Deben aparecer copiados exactamente igual, junto al elemento al que pertenecen:\n' + faltantes(texto).join('\n');
  const r2 = await gemini(inp.prompt + extra, { maxTokens: 8192 });
  const texto2 = limpiar(r2.texto);
  if (texto2 && faltantes(texto2).length < faltantes(texto).length) texto = texto2;
}

if (!texto) texto = 'ERROR al generar la HV: ' + (r.err || 'sin respuesta de la IA');

// Ortografia: en español ningun verbo termina en "-izé" (es "-icé": realicé, estandaricé, optimicé)
texto = texto.replace(/([A-Za-zÁÉÍÓÚáéíóúñÑ]+)izé(?![A-Za-zÁÉÍÓÚáéíóúñÑ])/g, (_, raiz) => raiz + 'icé');

// Nombre y contacto NO los decide la IA: se copian textuales de la HV base (linea 1 y 2),
// asi un error de tipeo del modelo nunca llega al apellido, telefono ni enlaces de perfil.
const lineasBase = String(inp.hv_base || '').split('\n').map((l) => l.trim()).filter(Boolean);
const nombreBase = lineasBase[0] || '';
const contactoBase = lineasBase[1] || '';
if (texto.startsWith('TITULO:') && nombreBase) {
  texto = texto.replace(/^TITULO:[^\n|]*/m, () => 'TITULO: ' + nombreBase + ' ');
  if (!/^TITULO:.*\|/m.test(texto)) texto = texto.replace(/^TITULO:.*$/m, () => 'TITULO: ' + nombreBase);
}
if (contactoBase) {
  if (/^CONTACTO:.*$/m.test(texto)) texto = texto.replace(/^CONTACTO:.*$/m, () => 'CONTACTO: ' + contactoBase);
  else if (texto.startsWith('TITULO:')) texto = texto.replace(/^(TITULO:.*)$/m, (l) => l + '\nCONTACTO: ' + contactoBase);
}

return [{ json: { url: inp.url, hv_adaptada: texto, enlaces_faltantes: faltantes(texto) } }];

const ctx = $('Loop ofertas').item.json;
const docId = $('Crear Google Doc').item.json.id;
const pdfId = $('Nombrar PDF').item.json.id;
const scoring = $('Recalcular match').item.json;
return [{ json: {
  url: ctx.url,
  titulo: ctx.titulo,
  empresa: ctx.empresa,
  hv_adaptada: 'https://docs.google.com/document/d/' + docId + '/edit',
  hv_pdf: 'https://drive.google.com/file/d/' + pdfId + '/view',
  match_pct: scoring.match_pct,
  ats_tip: scoring.ats_tip,
  posible_alucinacion: scoring.posible_alucinacion || ''
}}];

// Convierte la HV con marcadores (TITULO:/CONTACTO:/SECCION:/"- ") en:
//  1) el texto plano final (fullText) que se inserta de una sola vez en el Doc
//  2) la lista de requests de formato (negrita, tamaños, bullets) de la Google Docs API,
//     calculados con los indices exactos de caracteres dentro de fullText.
// Todo se manda en UN solo batchUpdate: primero el insertText, y como ese request se
// ejecuta primero, los requests de formato de ahi en mas ya pueden usar indices fijos.

const docId = $('Crear Google Doc').item.json.id;
const raw = ($('Generar HV con IA').item.json.hv_adaptada || '').replace(/\r\n/g, '\n');
const lineasRaw = raw.split('\n');

let fullText = '';
const segmentos = []; // {start, end, tipo}
let bulletBuffer = null;

function agregar(texto, tipo) {
  const start = fullText.length;
  fullText += texto;
  const end = fullText.length;
  if (tipo) segmentos.push({ start, end, tipo });
  return { start, end };
}

function cerrarBullets() {
  if (bulletBuffer) {
    segmentos.push({ start: bulletBuffer.start, end: bulletBuffer.end, tipo: 'bullet' });
    bulletBuffer = null;
  }
}

for (let i = 0; i < lineasRaw.length; i++) {
  const linea = lineasRaw[i];

  if (/^TITULO:/i.test(linea)) {
    cerrarBullets();
    agregar(linea.replace(/^TITULO:\s*/i, ''), 'titulo');
    agregar('\n');
    continue;
  }
  if (/^CONTACTO:/i.test(linea)) {
    cerrarBullets();
    agregar(linea.replace(/^CONTACTO:\s*/i, ''), 'contacto');
    agregar('\n');
    continue;
  }
  if (/^SECCION:/i.test(linea)) {
    cerrarBullets();
    agregar('\n');
    agregar(linea.replace(/^SECCION:\s*/i, '').trim(), 'seccion');
    agregar('\n');
    continue;
  }
  if (/^\s*-\s+/.test(linea)) {
    const texto = linea.replace(/^\s*-\s+/, '');
    const { end } = agregar(texto);
    agregar('\n');
    if (!bulletBuffer) bulletBuffer = { start: end - texto.length };
    bulletBuffer.end = end + 1;
    continue;
  }
  if (linea.trim() === '') {
    cerrarBullets();
    agregar('\n');
    continue;
  }
  cerrarBullets();
  agregar(linea, 'body');
  agregar('\n');
}
cerrarBullets();

if (!fullText.trim()) fullText = '(No se pudo generar la HV, revisar la ejecucion en n8n.)\n';

const requests = [
  { insertText: { location: { index: 1 }, text: fullText } }
];

for (const s of segmentos) {
  const startIndex = s.start + 1;
  const endIndex = s.end + 1;
  if (startIndex >= endIndex) continue;
  const range = { startIndex, endIndex };

  if (s.tipo === 'titulo') {
    requests.push({ updateTextStyle: { range, textStyle: { bold: true, fontSize: { magnitude: 16, unit: 'PT' } }, fields: 'bold,fontSize' } });
  } else if (s.tipo === 'contacto') {
    requests.push({ updateTextStyle: { range, textStyle: { italic: true, fontSize: { magnitude: 9.5, unit: 'PT' }, foregroundColor: { color: { rgbColor: { red: 0.35, green: 0.35, blue: 0.35 } } } }, fields: 'italic,fontSize,foregroundColor' } });
  } else if (s.tipo === 'seccion') {
    requests.push({ updateTextStyle: { range, textStyle: { bold: true, fontSize: { magnitude: 12, unit: 'PT' }, foregroundColor: { color: { rgbColor: { red: 0.10, green: 0.25, blue: 0.55 } } } }, fields: 'bold,fontSize,foregroundColor' } });
    requests.push({ updateParagraphStyle: { range, paragraphStyle: { spaceAbove: { magnitude: 10, unit: 'PT' }, spaceBelow: { magnitude: 3, unit: 'PT' }, borderBottom: { width: { magnitude: 0.5, unit: 'PT' }, padding: { magnitude: 1, unit: 'PT' }, dashStyle: 'SOLID', color: { color: { rgbColor: { red: 0.75, green: 0.75, blue: 0.75 } } } } }, fields: 'spaceAbove,spaceBelow,borderBottom' } });
  } else if (s.tipo === 'body') {
    requests.push({ updateTextStyle: { range, textStyle: { fontSize: { magnitude: 10.5, unit: 'PT' } }, fields: 'fontSize' } });
  } else if (s.tipo === 'bullet') {
    requests.push({ updateTextStyle: { range, textStyle: { fontSize: { magnitude: 10.5, unit: 'PT' } }, fields: 'fontSize' } });
    requests.push({ createParagraphBullets: { range, bulletPreset: 'BULLET_DISC_CIRCLE_SQUARE' } });
  }
}

// Cada URL del texto (LinkedIn, portafolio, titulo, certificados) queda como enlace clicable
for (const m of fullText.matchAll(/https?:\/\/[^\s|)]+/g)) {
  const startIndex = m.index + 1;
  requests.push({ updateTextStyle: { range: { startIndex, endIndex: startIndex + m[0].length }, textStyle: { link: { url: m[0] } }, fields: 'link' } });
}

return [{ json: { documentId: docId, requests } }];

// Chequeo anti-alucinacion: compara la HV adaptada contra la HV base + los datos de la
// oferta, y marca palabras que no aparecen en ninguno de los dos. Heuristico por texto
// (no otra llamada a IA) -> es una alerta para que REVISES antes de mandar la HV, no un
// bloqueo automatico ni una prueba definitiva. Va a tener algun falso positivo con nombres
// propios o conectores, eso es esperable.
const ctx = $('Loop ofertas').item.json;
const hvBase = ctx.hv_base || '';
const hvAdaptada = $input.first().json.hv_adaptada || '';

function normalizar(txt) {
  return String(txt).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

// Mencionar el titulo/empresa/ubicacion de ESTA oferta no es alucinar, es contextualizar.
const permitido = normalizar([hvBase, ctx.titulo, ctx.empresa, ctx.ubicacion].filter(Boolean).join(' '));

// Saca los marcadores de formato (TITULO:/CONTACTO:/SECCION:) antes de analizar el contenido
const contenido = hvAdaptada.replace(/^(TITULO|CONTACTO|SECCION):\s*/gim, '');

// Candidatos a "afirmacion verificable": palabras que arrancan con mayuscula (nombres propios,
// tecnologias, herramientas, empresas), 3+ letras.
const TOKEN_RE = /\b[A-ZÁÉÍÓÚÑ][A-Za-zÀ-ÿ0-9+.#/-]{2,}\b/g;
const candidatos = new Set(contenido.match(TOKEN_RE) || []);

const IGNORAR = new Set([
  'El','La','Los','Las','Un','Una','Con','Para','Por','En','De','Del','Y','O','Se','Su','Sus',
  'Que','Como','Mas','Este','Esta','Estos','Estas','Entre','Sin','Sobre','Desde','Hasta','Durante',
  'Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'
]);

const sospechosos = [];
for (const token of candidatos) {
  if (IGNORAR.has(token)) continue;
  if (!permitido.includes(normalizar(token))) {
    sospechosos.push(token);
  }
}

// Enlaces de la HV base que no quedaron en la adaptada (perfil y certificados): alerta prioritaria
const faltan = $input.first().json.enlaces_faltantes || [];
const alertas = [];
if (faltan.length) alertas.push('FALTAN ENLACES: ' + faltan.join(' '));
if (sospechosos.length) alertas.push(sospechosos.slice(0, 15).join(', '));
return [{ json: { hv_adaptada: hvAdaptada, posible_alucinacion: alertas.join(' | ') } }];

// Recalcula el match con la HV ya adaptada (para saber cuanto mejoro)
const inp = $input.first().json;
const ctx = $('Loop ofertas').item.json;
const cfg = $('Config (API key + HV base)').first().json;
const desc = $('Armar prompt').item.json.desc || '';
// ---- Utilidades compartidas: Gemini (API de Google AI Studio) + lectura de ofertas ----
const helpers = this.helpers;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Llama a Gemini por su endpoint compatible con OpenAI. Reintenta ante 429/5xx y, si el
// modelo principal sigue fallando (cuota o saturacion), cae a los modelos "lite" (cuota aparte).
async function gemini(prompt, { maxTokens = 8192, json = false } = {}) {
  const key = String(cfg.gemini_api_key || '').trim();
  if (!key) throw new Error('GEMINI_API_KEY vacia: revisa el .env y reinicia el contenedor (docker compose up -d).');
  const modelos = [cfg.gemini_model || 'gemini-3.8-flash', 'gemini-flash-lite-latest', 'gemini-3.5-flash-lite'];
  let err = '';
  for (let intento = 0; intento < 5; intento++) {
    const model = modelos[[0, 0, 1, 1, 2][intento]];
    try {
      const body = { model, messages: [{ role: 'user', content: prompt }], max_tokens: maxTokens, temperature: 0.2, reasoning_effort: 'low' };
      if (json) body.response_format = { type: 'json_object' };
      const resp = await helpers.httpRequest({
        method: 'POST',
        url: 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions',
        headers: { Authorization: 'Bearer ' + key, 'content-type': 'application/json' },
        body,
        json: true,
        timeout: 120000
      });
      const choice = (resp.choices || [])[0];
      const texto = ((choice && choice.message && choice.message.content) || '').trim();
      if (texto) return { texto, err: '' };
      err = 'Gemini sin texto: ' + JSON.stringify(resp).slice(0, 200);
    } catch (e) {
      err = (e.message || String(e)).slice(0, 300);
    }
    await sleep(intento === 0 ? 10000 : 25000);
  }
  return { texto: '', err };
}

function decodeEntities(str) {
  return String(str)
    .replace(/&#x([0-9A-Fa-f]+);/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)))
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'");
}
function limpiarHtml(str) {
  return decodeEntities(String(str)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' '))
    .replace(/\s+/g, ' ')
    .trim();
}

// Saca la descripcion de la oferta. Primero intenta el JSON-LD "JobPosting" (LinkedIn,
// Computrabajo y Elempleo lo publican), que trae solo la descripcion sin menus ni footer;
// si no esta, usa el texto plano de toda la pagina.
function extraerDescripcion(html, maxChars) {
  const s = String(html || '');
  const bloques = s.match(/<script[^>]*application\/ld\+json[^>]*>[\s\S]*?<\/script>/gi) || [];
  for (const b of bloques) {
    try {
      const data = JSON.parse(b.replace(/^<script[^>]*>/i, '').replace(/<\/script>$/i, ''));
      const lista = Array.isArray(data) ? data : (data['@graph'] || [data]);
      for (const d of lista) {
        if (d && d.description && /JobPosting/i.test(String(d['@type'] || ''))) {
          return limpiarHtml(decodeEntities(d.description)).slice(0, maxChars);
        }
      }
    } catch (e) { /* JSON-LD invalido: probar el siguiente */ }
  }
  return limpiarHtml(s).slice(0, maxChars);
}

async function traerDescripcion(url, maxChars) {
  try {
    const resp = await helpers.httpRequest({
      method: 'GET',
      url,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'es-CO,es;q=0.9,en;q=0.8',
        'Referer': 'https://www.google.com/'
      },
      timeout: 20000
    });
    const raw = (resp && (resp.body || resp.data)) || resp || '';
    return extraerDescripcion(typeof raw === 'string' ? raw : JSON.stringify(raw), maxChars);
  } catch (e) {
    return '';
  }
}

const prompt = [
  'Eres un evaluador de compatibilidad entre una hoja de vida (HV) y una oferta laboral.',
  'Responde SOLO con JSON valido, sin markdown, con este formato exacto:',
  '{"match": <entero 0-100>, "tip": "<max 15 palabras: que keyword de la oferta conviene resaltar en la HV>"}',
  '',
  '=== HV DEL CANDIDATO (version ya adaptada a esta oferta) ===',
  inp.hv_adaptada,
  '',
  '=== OFERTA ===',
  'Puesto: ' + (ctx.titulo || ''),
  'Empresa: ' + (ctx.empresa || ''),
  'Descripcion: ' + desc
].join('\n');

const r = await gemini(prompt, { maxTokens: 1024, json: true });

let match_pct = (ctx.match_pct !== undefined && ctx.match_pct !== null && ctx.match_pct !== '') ? ctx.match_pct : '';
let ats_tip = ctx.ats_tip || '';
if (r.texto) {
  try {
    const jm = r.texto.match(/\{[\s\S]*\}/);
    const parsed = JSON.parse(jm ? jm[0] : r.texto);
    if (parsed.match !== undefined && parsed.match !== null) {
      match_pct = Number(parsed.match);
      ats_tip = parsed.tip || '';
    }
  } catch (e) {
    // no se pudo interpretar: se deja el match/tip que la fila ya tenia
  }
}

return [{ json: { url: ctx.url, hv_adaptada: inp.hv_adaptada, posible_alucinacion: inp.posible_alucinacion || '', match_pct, ats_tip } }];

