// El trigger corre cada 15 min; si generar las HV (IA + Google Doc) tarda mas que eso,
// una corrida nueva podria arrancar mientras la anterior sigue viva y duplicar documentos.
// Guardamos un timestamp de 'corriendo desde' y nos salteamos esta corrida si sigue vigente.
// Expira sola a los 14 min por si una corrida anterior quedo colgada.
// (Los scrapers corren 9:05-10:00 y este workflow arranca 10:05, asi no escriben la
// planilla al mismo tiempo.)
const sd = $getWorkflowStaticData('global');
const ahora = Date.now();
if (sd.procesandoDesde && (ahora - sd.procesandoDesde) < 14 * 60 * 1000) {
  return [];
}
sd.procesandoDesde = ahora;
return $input.all();

// ID de la carpeta HV, venga de la busqueda (files[0]) o de la creacion (id)
const j = $input.first().json;
const folderId = (j.files && j.files[0] && j.files[0].id) || j.id;
if (!folderId) throw new Error('No se pudo obtener la carpeta HV del Drive');
